  const [query, setQuery] = useState('');
  const [flight, setFlight] = useState(currentFlight);

  return (
    <Layout>
      <SearchField value={query} onChange={setQuery} />
      <SeatMap flight={flight} />          {/* 300+ seat components */}
      <PassengerList flight={flight} />
      <FareSummary flight={flight} />
