function GateBanner({ flightId, agentId }: Props) {
  const [status, setStatus] = useState<GateStatus | null>(null);
  const [seenCount, setSeenCount] = useState(0);
  const agentRef = useRef(agentId);
  useEffect(() => { agentRef.current = agentId; }, [agentId]);

  useEffect(() => {
    const sub = gateFeed.subscribe(flightId, (next) => {
      setStatus(next);
      setSeenCount(c => c + 1);
      logView(agentRef.current, flightId, next.code);
    });
    return () => sub.unsubscribe();
  }, [flightId]);

  return <Banner status={status} seen={seenCount} />;
}
```

